import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testTeamFound() {
        val teams = listOf(4215, 1234, 5678)
        Assert.assertTrue(isTeamPresent(teams, 4215))
    }

    @Test
    fun testTeamNotFound() {
        val teams = listOf(4215, 1234, 5678)
        Assert.assertFalse(isTeamPresent(teams, 9999))
    }

    @Test
    fun testMiddleElement() {
        val teams = listOf(4215, 1234, 5678)
        Assert.assertTrue(isTeamPresent(teams, 1234))
    }

    @Test
    fun testEmptyList() {
        val teams = listOf<Int>()
        Assert.assertFalse(isTeamPresent(teams, 4215))
    }
}
